import { useEffect, useMemo, useState } from "react";
import { AlertCircle, ArrowDown, ArrowUp, CheckCircle2, ExternalLink, FileText, LoaderCircle, MailWarning, Plus, RefreshCw, Save, Search, Settings2, UsersRound } from "lucide-react";
import { PageHeader } from "../components/content/page-elements";
import { Button } from "../components/ui/button";
import { Dialog, DialogContent } from "../components/ui/dialog";
import { confirmApplicationEmailSent, fetchAdminApplications, fetchAdminForm, publishAdminForm, retryApplicationEmail } from "../features/recruitment/api";
import { hasRecruitmentApi } from "../features/recruitment/config";
import { GoogleAdminLogin } from "../features/recruitment/google-admin-login";
import type { AdminApplication, AdminApplicationsResponse, RecruitmentFieldType, RecruitmentFormConfig } from "../features/recruitment/types";

const PAGE_SIZE = 10;
const fieldTypes: RecruitmentFieldType[] = ["text", "textarea", "email", "url", "radio", "select", "checkbox"];
const inputClass = "min-h-11 w-full rounded-xl border border-black/10 bg-white px-3 text-sm outline-none focus:border-vic-blue focus:ring-4 focus:ring-vic-blue/10";

function StatCard({ icon: Icon, label, value }: { icon: typeof UsersRound; label: string; value: string | number }) {
  return <div className="rounded-[1.5rem] border border-black/10 bg-white p-5"><Icon size={19} className="text-vic-blue" /><p className="mt-5 text-2xl font-bold">{value}</p><p className="mt-1 text-sm text-vic-muted">{label}</p></div>;
}

function ApplicationList({ data, idToken, onEmailStatusChange, onRefresh }: { data: AdminApplicationsResponse; idToken: string; onEmailStatusChange: (id: string, status: AdminApplication["emailStatus"], error?: string | null) => void; onRefresh: () => void }) {
  const [query, setQuery] = useState("");
  const [department, setDepartment] = useState("all");
  const [campaign, setCampaign] = useState("all");
  const [emailStatus, setEmailStatus] = useState("all");
  const [page, setPage] = useState(1);
  const [selected, setSelected] = useState<AdminApplication | null>(null);
  const [retrying, setRetrying] = useState("");
  const filtered = useMemo(() => data.applications.filter((item) => {
    const haystack = `${item.fullName} ${item.schoolEmail} ${item.studentId}`.toLocaleLowerCase("vi");
    return haystack.includes(query.trim().toLocaleLowerCase("vi")) && (department === "all" || item.department === department) && (campaign === "all" || item.campaignId === campaign) && (emailStatus === "all" || item.emailStatus === emailStatus);
  }).sort((a, b) => Date.parse(b.submittedAt) - Date.parse(a.submittedAt)), [campaign, data.applications, department, emailStatus, query]);
  const campaigns = useMemo(() => Array.from(new Set(data.applications.map((item) => item.campaignId))), [data.applications]);
  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const shown = filtered.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);
  useEffect(() => setPage(1), [query, department, campaign, emailStatus]);
  const retry = async (applicationId: string, allowPossibleDuplicate = false) => { setRetrying(applicationId); try { await retryApplicationEmail(idToken, applicationId, allowPossibleDuplicate); onEmailStatusChange(applicationId, "pending", null); setSelected((current) => current?.applicationId === applicationId ? { ...current, emailStatus: "pending", emailError: null } : current); } catch (error) { window.alert(error instanceof Error ? error.message : "Không thể xếp email để gửi lại."); } finally { setRetrying(""); } };
  const confirmSent = async (applicationId: string) => { setRetrying(applicationId); try { await confirmApplicationEmailSent(idToken, applicationId); onEmailStatusChange(applicationId, "sent", "Đã xác nhận thủ công bởi quản trị viên."); setSelected((current) => current?.applicationId === applicationId ? { ...current, emailStatus: "sent", emailError: "Đã xác nhận thủ công bởi quản trị viên." } : current); } catch (error) { window.alert(error instanceof Error ? error.message : "Không thể xác nhận email."); } finally { setRetrying(""); } };
  return <section className="mt-8 rounded-[2rem] border border-black/10 bg-white p-5 md:p-7">
    <div className="flex flex-col justify-between gap-4 lg:flex-row lg:items-center"><div><h2 className="text-xl font-bold">Danh sách đơn</h2><p className="mt-1 text-sm text-vic-muted">Chỉ xem; sửa hoặc xóa trực tiếp trong Google Sheet.</p></div><div className="flex flex-wrap gap-2"><Button variant="secondary" size="sm" onClick={onRefresh}><RefreshCw size={15} /> Làm mới trạng thái</Button>{data.sheetUrl && <Button asChild variant="secondary" size="sm"><a href={data.sheetUrl} target="_blank" rel="noreferrer">Mở Google Sheet <ExternalLink size={15} /></a></Button>}</div></div>
    <div className="mt-6 grid gap-3 lg:grid-cols-[1fr_11rem_11rem_11rem]"><label className="relative"><span className="sr-only">Tìm đơn</span><Search className="absolute left-3 top-3 text-vic-muted" size={18} /><input className={`${inputClass} pl-10`} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Tên, email hoặc MSSV" /></label><select className={inputClass} value={department} onChange={(event) => setDepartment(event.target.value)}><option value="all">Tất cả ban</option><option value="hoc_tap">Ban Học tập</option><option value="truyen_thong">Ban Truyền thông</option></select><select className={inputClass} value={campaign} onChange={(event) => setCampaign(event.target.value)}><option value="all">Tất cả đợt</option>{campaigns.map((item) => <option key={item} value={item}>{item}</option>)}</select><select className={inputClass} value={emailStatus} onChange={(event) => setEmailStatus(event.target.value)}><option value="all">Mọi trạng thái email</option><option value="pending">Đang chờ</option><option value="failed">Thất bại</option><option value="needs_review">Cần kiểm tra</option><option value="sent">Đã gửi</option></select></div>
    <div className="mt-5 overflow-x-auto"><table className="w-full min-w-[48rem] text-left text-sm"><thead className="border-b border-black/10 text-xs uppercase tracking-wider text-vic-muted"><tr><th className="px-3 py-3">Ứng viên</th><th className="px-3 py-3">MSSV</th><th className="px-3 py-3">Ban</th><th className="px-3 py-3">Thời gian</th><th className="px-3 py-3">Email</th></tr></thead><tbody>{shown.map((item) => <tr key={item.applicationId} tabIndex={0} onClick={() => setSelected(item)} onKeyDown={(event) => { if (event.key === "Enter") setSelected(item); }} className="cursor-pointer border-b border-black/5 hover:bg-vic-blue-soft/50 focus:bg-vic-blue-soft"><td className="px-3 py-4"><strong>{item.fullName}</strong><span className="mt-1 block text-xs text-vic-muted">{item.schoolEmail}</span></td><td className="px-3 py-4 font-mono">{item.studentId}</td><td className="px-3 py-4">{item.departmentLabel}</td><td className="px-3 py-4">{new Intl.DateTimeFormat("vi-VN", { dateStyle: "short", timeStyle: "short", timeZone: "Asia/Ho_Chi_Minh" }).format(new Date(item.submittedAt))}</td><td className="px-3 py-4"><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${item.emailStatus === "sent" ? "bg-green-50 text-green-700" : item.emailStatus === "failed" || item.emailStatus === "needs_review" ? "bg-red-50 text-red-800" : "bg-amber-50 text-amber-800"}`}>{item.emailStatus === "needs_review" ? "Cần kiểm tra" : item.emailStatus === "pending" ? "Đang chờ" : item.emailStatus === "failed" ? "Thất bại" : "Đã gửi"}</span></td></tr>)}</tbody></table>{!shown.length && <p className="py-12 text-center text-vic-muted">Không có đơn phù hợp.</p>}</div>
    <div className="mt-5 flex items-center justify-between text-sm"><span>{filtered.length} kết quả</span><div className="flex items-center gap-2"><Button size="sm" variant="secondary" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Trước</Button><span>{page}/{pageCount}</span><Button size="sm" variant="secondary" disabled={page >= pageCount} onClick={() => setPage((value) => value + 1)}>Sau</Button></div></div>
    <Dialog open={Boolean(selected)} onOpenChange={(open) => { if (!open) setSelected(null); }}>{selected && <DialogContent title={selected.fullName} description={`${selected.applicationId} · ${selected.schoolEmail}`} className="max-h-[86vh] overflow-y-auto md:w-[min(calc(100%-2.25rem),48rem)]"><dl className="mt-7 divide-y divide-black/10">{selected.answersSnapshot.map((answer) => <div key={answer.fieldId} className="py-4"><dt className="text-xs font-semibold uppercase tracking-wider text-vic-muted">{answer.label}</dt><dd className="mt-1 whitespace-pre-wrap break-words text-sm leading-6">{answer.optionLabel ?? (answer.value === true ? "Đã đồng ý" : String(answer.value || "—"))}</dd></div>)}</dl>{selected.emailError && <p className="mt-6 rounded-xl bg-red-50 p-3 text-xs text-red-800">{selected.emailError}</p>}{selected.emailStatus !== "sent" && <div className="mt-6 flex flex-wrap gap-3">{selected.emailStatus === "needs_review" ? <><Button disabled={retrying === selected.applicationId} onClick={() => void confirmSent(selected.applicationId)}>{retrying === selected.applicationId ? <LoaderCircle size={16} className="animate-spin" /> : <CheckCircle2 size={16} />} Đã kiểm tra: email đã gửi</Button><Button variant="secondary" disabled={retrying === selected.applicationId} onClick={() => { if (window.confirm("Chỉ tiếp tục nếu đã kiểm tra hộp thư gửi và email xác nhận chưa được gửi. Có thể người nộp nhận email trùng.")) void retry(selected.applicationId, true); }}><RefreshCw size={16} /> Gửi lại dù có thể trùng</Button></> : <Button disabled={retrying === selected.applicationId} onClick={() => void retry(selected.applicationId)}>{retrying === selected.applicationId ? <LoaderCircle size={16} className="animate-spin" /> : <RefreshCw size={16} />} Xếp email để gửi lại</Button>}</div>}</DialogContent>}</Dialog>
  </section>;
}

function FormEditor({ initial, idToken, onPublished }: { initial: RecruitmentFormConfig; idToken: string; onPublished: (config: RecruitmentFormConfig) => void }) {
  const [draft, setDraft] = useState(() => structuredClone(initial));
  const [dirty, setDirty] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [previewMode, setPreviewMode] = useState<"desktop" | "mobile">("desktop");
  const update = (recipe: (current: RecruitmentFormConfig) => void) => { setDraft((current) => { const next = structuredClone(current); recipe(next); return next; }); setDirty(true); setMessage(""); };
  useEffect(() => { const warn = (event: BeforeUnloadEvent) => { if (dirty) event.preventDefault(); }; window.addEventListener("beforeunload", warn); return () => window.removeEventListener("beforeunload", warn); }, [dirty]);
  const move = (index: number, offset: number) => update((current) => { const fields = [...current.fields].sort((a, b) => a.sortOrder - b.sortOrder); const target = index + offset; if (target < 0 || target >= fields.length) return; [fields[index], fields[target]] = [fields[target], fields[index]]; fields.forEach((field, position) => { field.sortOrder = position + 1; }); current.fields = fields; });
  const addField = () => update((current) => { const suffix = Date.now().toString().slice(-6); current.fields.push({ fieldId: `new_field_${suffix}`, label: "Câu hỏi mới", type: "text", required: false, active: true, sortOrder: current.fields.length + 1, section: "Thông tin bổ sung", helpText: "", options: [] }); });
  const publish = async () => {
    if (!draft.formTitle.trim() || !draft.fields.some((field) => field.fieldId === "school_email" && field.active) || !draft.fields.some((field) => field.fieldId === "consent" && field.active && field.required)) { setMessage("Tiêu đề, email và consent bắt buộc phải hợp lệ."); return; }
    setSaving(true); setMessage("");
    try { const next = await publishAdminForm(idToken, draft, initial.formVersion); setDraft(next); setDirty(false); onPublished(next); setMessage(`Đã xuất bản phiên bản ${next.formVersion}.`); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Không thể xuất bản."); }
    finally { setSaving(false); }
  };
  return <section className="mt-8 rounded-[2rem] border border-black/10 bg-white p-5 md:p-7">
    <div className="flex flex-col justify-between gap-4 md:flex-row md:items-center"><div><h2 className="text-xl font-bold">Trình chỉnh form</h2><p className="mt-1 text-sm text-vic-muted">Bản nháp chỉ tồn tại trong phiên này cho đến khi xuất bản.</p></div><div className="flex items-center gap-3"><span className={`rounded-full px-3 py-1 text-xs font-semibold ${draft.isOpen ? "bg-green-50 text-green-700" : "bg-slate-100 text-slate-700"}`}>{draft.isOpen ? "Đang mở" : "Đang đóng"}</span><Button onClick={publish} disabled={!dirty || saving}>{saving ? <LoaderCircle className="animate-spin" size={16} /> : <Save size={16} />} Xuất bản thay đổi</Button></div></div>
    <div className="mt-7 grid gap-4 md:grid-cols-2"><label className="text-sm font-semibold">Tiêu đề<input className={`${inputClass} mt-2`} value={draft.formTitle} onChange={(event) => update((current) => { current.formTitle = event.target.value; })} /></label><label className="text-sm font-semibold">Trạng thái<select className={`${inputClass} mt-2`} value={draft.isOpen ? "open" : "closed"} onChange={(event) => update((current) => { current.isOpen = event.target.value === "open"; })}><option value="closed">Đóng nhận đơn</option><option value="open">Mở nhận đơn</option></select></label><label className="text-sm font-semibold md:col-span-2">Mô tả<textarea className={`${inputClass} mt-2 py-3`} rows={3} value={draft.formDescription} onChange={(event) => update((current) => { current.formDescription = event.target.value; })} /></label><label className="text-sm font-semibold md:col-span-2">Thông báo khi đóng<textarea className={`${inputClass} mt-2 py-3`} rows={3} value={draft.closedMessage} onChange={(event) => update((current) => { current.closedMessage = event.target.value; })} /></label><label className="text-sm font-semibold md:col-span-2">Thông báo thành công<textarea className={`${inputClass} mt-2 py-3`} rows={2} value={draft.successMessage} onChange={(event) => update((current) => { current.successMessage = event.target.value; })} /></label></div>
    <div className="mt-8 flex items-center justify-between"><h3 className="font-bold">Các trường</h3><Button variant="secondary" size="sm" onClick={addField}><Plus size={15} /> Thêm trường</Button></div>
    <div className="mt-4 space-y-4">{[...draft.fields].sort((a, b) => a.sortOrder - b.sortOrder).map((field, index) => <div key={field.fieldId} className="rounded-2xl border border-black/10 bg-vic-bg p-4"><div className="flex flex-wrap items-center gap-2"><code className="mr-auto text-xs text-vic-muted">{field.fieldId}</code><Button variant="ghost" size="icon" aria-label="Đưa lên" disabled={index === 0} onClick={() => move(index, -1)}><ArrowUp size={16} /></Button><Button variant="ghost" size="icon" aria-label="Đưa xuống" disabled={index === draft.fields.length - 1} onClick={() => move(index, 1)}><ArrowDown size={16} /></Button></div><div className="mt-3 grid gap-3 md:grid-cols-2"><label className="text-xs font-semibold">Nhãn<input className={`${inputClass} mt-1`} value={field.label} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.label = event.target.value; })} /></label><label className="text-xs font-semibold">Nhóm<input className={`${inputClass} mt-1`} value={field.section} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.section = event.target.value; })} /></label><label className="text-xs font-semibold">Loại<select className={`${inputClass} mt-1`} disabled={!field.fieldId.startsWith("new_field_")} value={field.type} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.type = event.target.value as RecruitmentFieldType; })}>{fieldTypes.map((type) => <option key={type} value={type}>{type}</option>)}</select></label><label className="text-xs font-semibold">Trợ giúp<input className={`${inputClass} mt-1`} value={field.helpText ?? ""} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.helpText = event.target.value; })} /></label></div><div className="mt-3 flex flex-wrap gap-5 text-sm"><label className="flex items-center gap-2"><input type="checkbox" checked={field.required} disabled={field.system} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.required = event.target.checked; })} /> Bắt buộc</label><label className="flex items-center gap-2"><input type="checkbox" checked={field.active} disabled={field.system} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.active = event.target.checked; })} /> Hiển thị</label></div>{field.options.length > 0 && <div className="mt-4 space-y-2 border-t border-black/10 pt-4">{field.options.map((option) => <div key={option.optionId} className="grid gap-2 md:grid-cols-[7rem_1fr_1fr_auto]"><code className="self-center text-xs">{option.optionId}</code><input aria-label={`Nhãn ${option.optionId}`} className={inputClass} value={option.label} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.options.find((item) => item.optionId === option.optionId)!.label = event.target.value; })} /><input aria-label={`Link ${option.optionId}`} className={inputClass} value={option.infoUrl ?? ""} placeholder="Link giới thiệu" onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.options.find((item) => item.optionId === option.optionId)!.infoUrl = event.target.value; })} /><label className="flex items-center gap-2 px-2 text-xs"><input type="checkbox" checked={option.active} onChange={(event) => update((current) => { current.fields.find((item) => item.fieldId === field.fieldId)!.options.find((item) => item.optionId === option.optionId)!.active = event.target.checked; })} />Hiện</label></div>)}</div>}</div>)}</div>
    <div className="mt-8 border-t border-black/10 pt-7"><div className="flex items-center justify-between gap-3"><div><h3 className="font-bold">Xem trước bản nháp</h3><p className="mt-1 text-sm text-vic-muted">Preview không gửi dữ liệu.</p></div><div className="flex rounded-full bg-vic-surface p-1"><button className={`rounded-full px-3 py-2 text-xs font-semibold ${previewMode === "desktop" ? "bg-white shadow-sm" : ""}`} onClick={() => setPreviewMode("desktop")}>Desktop</button><button className={`rounded-full px-3 py-2 text-xs font-semibold ${previewMode === "mobile" ? "bg-white shadow-sm" : ""}`} onClick={() => setPreviewMode("mobile")}>Mobile</button></div></div><div className={`mx-auto mt-5 rounded-[1.5rem] border border-black/10 bg-vic-bg p-5 transition-[max-width] ${previewMode === "mobile" ? "max-w-sm" : "max-w-3xl"}`}><h4 className="text-xl font-bold">{draft.formTitle}</h4><p className="mt-2 text-sm leading-6 text-vic-muted">{draft.formDescription}</p><div className="mt-6 space-y-5">{draft.fields.filter((field) => field.active).sort((a, b) => a.sortOrder - b.sortOrder).map((field) => <div key={field.fieldId}><p className="text-sm font-semibold">{field.label} {field.required && <span className="text-vic-blue">*</span>}</p>{field.helpText && <p className="mt-1 text-xs text-vic-muted">{field.helpText}</p>}<div className="mt-2 min-h-10 rounded-xl border border-black/10 bg-white px-3 py-2 text-sm text-vic-muted">{field.options.filter((option) => option.active).map((option) => option.label).join(" · ") || (field.type === "checkbox" ? "□ Xác nhận" : `Trường ${field.type}`)}</div></div>)}</div></div></div>
    <div className="mt-6 grid gap-3 rounded-2xl bg-vic-surface p-4 text-sm sm:grid-cols-2"><span>Email domain: <strong>@{draft.allowedEmailDomain}</strong></span><span>Cooldown cố định: <strong>{draft.cooldownMinutes} phút</strong></span></div>{message && <p className={`mt-5 rounded-xl p-3 text-sm ${message.startsWith("Đã") ? "bg-green-50 text-green-800" : "bg-red-50 text-red-800"}`}>{message}</p>}
    <div className="mt-8 border-t border-black/10 pt-7"><h3 className="font-bold">Quản lý lựa chọn</h3><p className="mt-1 text-sm text-vic-muted">Thêm option ID ổn định cho trường radio/select; option đã xuất bản không bị xóa.</p><div className="mt-4 space-y-4">{draft.fields.filter((field) => field.type === "radio" || field.type === "select").map((field) => <div key={field.fieldId} className="rounded-2xl bg-vic-surface p-4"><div className="flex items-center justify-between gap-3"><div><p className="font-semibold">{field.label}</p><code className="text-xs text-vic-muted">{field.fieldId}</code></div><Button variant="secondary" size="sm" onClick={() => update((current) => { const target = current.fields.find((item) => item.fieldId === field.fieldId)!; const suffix = Date.now().toString().slice(-5); target.options.push({ fieldId: field.fieldId, optionId: `option_${suffix}`, label: "Lựa chọn mới", sortOrder: target.options.length + 1, active: true, infoUrl: null }); })}><Plus size={14} /> Thêm lựa chọn</Button></div><p className="mt-3 text-xs text-vic-muted">{field.options.length} lựa chọn · chỉnh nhãn, link và trạng thái ở thẻ trường phía trên.</p></div>)}</div></div>
  </section>;
}

export function RecruitmentAdminPage() {
  const [token, setToken] = useState(import.meta.env.DEV && !hasRecruitmentApi ? "local-prototype" : "");
  const [form, setForm] = useState<RecruitmentFormConfig | null>(null);
  const [applications, setApplications] = useState<AdminApplicationsResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const load = async (idToken: string) => { setLoading(true); setError(""); try { const [formData, applicationData] = await Promise.all([fetchAdminForm(idToken), fetchAdminApplications(idToken)]); setForm(formData); setApplications(applicationData); } catch (cause) { setError(cause instanceof Error ? cause.message : "Không thể tải dữ liệu quản trị."); } finally { setLoading(false); } };
  useEffect(() => { if (token) void load(token); }, [token]);
  const stats = useMemo(() => ({ total: applications?.total ?? 0, learning: applications?.applications.filter((item) => item.department === "hoc_tap").length ?? 0, media: applications?.applications.filter((item) => item.department === "truyen_thong").length ?? 0, emailIssues: applications?.applications.filter((item) => item.emailStatus !== "sent").length ?? 0 }), [applications]);
  return <main id="main"><PageHeader eyebrow="VIC ADMIN" title="Tuyển thành viên" description="Theo dõi đơn ứng tuyển và xuất bản cấu hình biểu mẫu mà không thay đổi dữ liệu lịch sử." />
    <section className="section-space pt-0"><div className="page-container">
      {!hasRecruitmentApi && import.meta.env.DEV && <p className="mb-6 rounded-2xl bg-amber-50 p-4 text-sm leading-6 text-amber-900"><strong>Prototype local:</strong> dữ liệu dưới đây là mẫu, không đọc hoặc ghi Google Sheet.</p>}
      {!hasRecruitmentApi && !import.meta.env.DEV ? <div className="glass-surface rounded-[2rem] p-8 text-center"><AlertCircle className="mx-auto text-amber-700" /><h2 className="mt-4 text-2xl font-bold">Admin dữ liệu thật chưa khả dụng</h2><p className="mx-auto mt-3 max-w-2xl leading-7 text-vic-muted">Cần cấu hình Apps Script URL và Google OAuth Client ID. Website không đưa admin secret vào frontend và không công khai danh sách ứng viên.</p></div> : !token ? <GoogleAdminLogin onCredential={setToken} /> : loading ? <div className="flex min-h-64 items-center justify-center gap-3"><LoaderCircle className="animate-spin text-vic-blue" /> Đang tải dữ liệu an toàn…</div> : error ? <div className="rounded-2xl bg-red-50 p-6 text-red-800"><p className="font-semibold">{error}</p><Button className="mt-5" onClick={() => void load(token)}><RefreshCw size={16} /> Thử lại</Button></div> : form && applications ? <>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5"><StatCard icon={UsersRound} label="Tổng số đơn" value={stats.total} /><StatCard icon={FileText} label="Ban Học tập" value={stats.learning} /><StatCard icon={FileText} label="Ban Truyền thông" value={stats.media} /><StatCard icon={MailWarning} label="Email cần xử lý" value={stats.emailIssues} /><StatCard icon={form.isOpen ? CheckCircle2 : Settings2} label="Trạng thái form" value={form.isOpen ? "Mở" : "Đóng"} /></div>
        <ApplicationList data={applications} idToken={token} onRefresh={() => void load(token)} onEmailStatusChange={(applicationId, emailStatus, emailError) => setApplications((current) => current ? { ...current, applications: current.applications.map((item) => item.applicationId === applicationId ? { ...item, emailStatus, emailError } : item) } : current)} /><FormEditor initial={form} idToken={token} onPublished={setForm} />
      </> : null}
    </div></section>
  </main>;
}
